  const [report,setReport]=useState<OperationsReport|null>(null);const [reportDays,setReportDays]=useState<7|30|90>(30);const [reportError,setReportError]=useState("");const [reportLoading,setReportLoading]=useState(false);const [reportReload,setReportReload]=useState(0);
  const [departmentDrafts,setDepartmentDrafts]=useState<Record<string,Department[]>>({});
