  const [sourcingCandidates,setSourcingCandidates]=useState<SourcingCandidate[]>([]);const [candidateLoadError,setCandidateLoadError]=useState("");const [candidateEditingId,setCandidateEditingId]=useState<string|null>(null);const [candidateName,setCandidateName]=useState("");const [candidateSupplier,setCandidateSupplier]=useState("");const [candidateUrl,setCandidateUrl]=useState("");const [candidatePrice,setCandidatePrice]=useState("");const [candidateCurrency,setCandidateCurrency]=useState("USD");const [candidateAvailability,setCandidateAvailability]=useState("");const [candidateEvidence,setCandidateEvidence]=useState("");const [shareCandidateIds,setShareCandidateIds]=useState<string[]>([]);const [memberOptionNote,setMemberOptionNote]=useState("");
  const [note,setNote]=useState("");const [checkTitle,setCheckTitle]=useState("");const [memberReply,setMemberReply]=useState("");const [businessReply,setBusinessReply]=useState("");const [action,setAction]=useState("");const [nextAction,setNextAction]=useState("");
  const [waitingOn,setWaitingOn]=useState("member");const [waitingReason,setWaitingReason]=useState("");const [transferDepartment,setTransferDepartment]=useState<Department>("sourcing");const [transferReason,setTransferReason]=useState("");
  const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");
