  async function run(actionFn:()=>Promise<void>,success:string){setBusy(true);setError("");setNotice("");try{await actionFn();setNotice(success);if(token)await refresh(token);}catch(reason){setError(reason instanceof Error?reason.message:"The operation could not be saved.");}finally{setBusy(false);}}
  async function claim(item:WorkItem){if(!token)return;await run(async()=>{await apiRequest(`/operations/work-items/${item.id}/claim`,token,{method:"POST"});},"Work claimed for 15 minutes.");}
  async function saveStatus(event:FormEvent){event.preventDefault();if(!token||!selected)return;await run(async()=>{await apiRequest(`/operations/work-items/${selected.id}`,token,{method:"PATCH",body:JSON.stringify({expected_version:selected.version,status:action,next_action:nextAction,waiting_on:action==="waiting"?waitingOn:null,waiting_reason:action==="waiting"?waitingReason:null,due_at:selected.due_at,reason:waitingReason||null})});},"Work status saved.");}
  async function sendMemberReply(event:FormEvent){event.preventDefault();if(!token||!selected||!memberReply.trim())return;const content=memberReply.trim();await run(async()=>{await apiRequest(`/operations/work-items/${selected.id}/member-reply`,token,{method:"POST",body:JSON.stringify({content})});setMemberReply("");},"Reply sent. The conversation is waiting for the member.");}
  async function sendBusinessReply(event:FormEvent){event.preventDefault();if(!token||!selected||!businessReply.trim())return;const content=businessReply.trim();let deliveryStatus="";await run(async()=>{const result=await apiRequest<{delivery_status:string}>(`/operations/work-items/${selected.id}/business-reply`,token,{method:"POST",body:JSON.stringify({content})});deliveryStatus=result.delivery_status;setBusinessReply("");},"Business reply saved.");if(deliveryStatus&&deliveryStatus!=="sent")setNotice(`Reply saved. Delivery status: ${deliveryStatus.replaceAll("_"," ")}.`);}
  async function returnToAutomation(){if(!token||!selected)return;await run(async()=>{await apiRequest(`/operations/work-items/${selected.id}/return-to-automation`,token,{method:"POST"});},"Handoff returned to automation and closed in staff work.");}
  async function transfer(event:FormEvent){event.preventDefault();if(!token||!selected)return;await run(async()=>{await apiRequest(`/operations/work-items/${selected.id}/transfer`,token,{method:"POST",body:JSON.stringify({expected_version:selected.version,department:transferDepartment,next_action:nextAction,reason:transferReason})});},"Work transferred with its audit reason.");}
  async function createDispute(event:FormEvent){event.preventDefault();if(!token||!selected||!requestContext||!disputeSummary.trim())return;setBusy(true);setError("");setNotice("");try{const result=await apiRequest<{dispute_case:DisputeCase;work_item:WorkItem}>(`/operations/work-items/${selected.id}/dispute-cases`,token,{method:"POST",body:JSON.stringify({category:disputeCategory,summary:disputeSummary.trim(),next_action:disputeNextAction.trim(),due_at:disputeDueAt?new Date(disputeDueAt).toISOString():null})});setDisputeSummary("");setFilterStatus("");setScope(canManage?"all":"available");setFilterDepartment("disputes");setItems(current=>[result.work_item,...current.filter(item=>item.id!==result.work_item.id)]);setSelected(result.work_item);setNotice("Separate dispute case opened in the Disputes queue. The request timeline is unchanged.");}catch(reason){setError(reason instanceof Error?reason.message:"The dispute case could not be opened.");}finally{setBusy(false);}}
  async function updateDispute(event:FormEvent){event.preventDefault();if(!token||!disputeCase)return;if(["resolved","closed"].includes(disputeStatus)&&!disputeResolution.trim()){setError("Add a resolution before resolving or closing the case.");return;}await run(async()=>{await apiRequest(`/operations/dispute-cases/${disputeCase.id}`,token,{method:"PATCH",body:JSON.stringify({expected_version:disputeCase.version,status:disputeStatus,resolution:disputeResolution.trim()||null})});if(selected)await loadDetails(token,selected);},"Dispute case updated and audited.");}
  async function addNote(event:FormEvent){event.preventDefault();if(!token||!selected)return;await run(async()=>{await apiRequest(`/operations/work-items/${selected.id}/notes`,token,{method:"POST",body:JSON.stringify({note})});setNote("");},"Internal note added. Mentioned active coworkers will be notified.");}
  const mentionMatch=note.match(/@([^\s@]*)$/);const mentionQuery=mentionMatch?.[1]?.toLowerCase();const mentionSuggestions=mentionMatch?mentionWorkers.filter(worker=>worker.email.includes(mentionQuery||"")||worker.label.toLowerCase().includes(mentionQuery||"")).slice(0,6):[];
  function insertMention(worker:MentionWorker){if(!mentionMatch)return;setNote(current=>current.replace(/@([^\s@]*)$/,`@${worker.email} `));}
  function editSourcingCandidate(candidate:SourcingCandidate){setCandidateEditingId(candidate.id);setCandidateName(candidate.product_name);setCandidateSupplier(candidate.supplier_name||"");setCandidateUrl(candidate.product_url);setCandidatePrice(candidate.price_amount===null?"":String(candidate.price_amount));setCandidateCurrency(candidate.currency||"USD");setCandidateAvailability(candidate.availability||"");setCandidateEvidence(candidate.evidence_note);}
